insert into public.services (slug, title_en, title_ar, tagline_en, tagline_ar, description_en, description_ar, sub_services, illustration, faqs, team_name_en, team_name_ar, team_description_en, team_description_ar, team_deliverables, icon, sort_order, published) values
  ('development', 'Development', 'البرمجة والتطوير', 'Software that ships and scales.', 'برمجيات تُطلَق بثقة وتنمو معك.', 'Custom web apps, platforms and integrations engineered for speed, security and the long run — from first commit to production.', 'تطبيقات ويب ومنصات وتكاملات مخصصة، مبنية للسرعة والأمان والاستمرارية — من أول سطر كود حتى الإطلاق.', '[{"en":"Web & mobile apps","ar":"تطبيقات الويب والجوال"},{"en":"E-commerce platforms","ar":"منصات التجارة الإلكترونية"},{"en":"ERP & CRM systems","ar":"أنظمة ERP وCRM"},{"en":"APIs & integrations","ar":"واجهات API والتكاملات"},{"en":"AI agents & n8n automation","ar":"وكلاء ذكاء اصطناعي وأتمتة n8n"}]'::jsonb, 'code', '[{"q":{"en":"Do you build on platforms or custom code?","ar":"هل تبنون على منصات جاهزة أم بكود مخصص؟"},"a":{"en":"Both. We recommend Salla, Shopify or WordPress when they fit, and custom builds (Next.js, Laravel, Node) when you need something they can''t do.","ar":"الاثنان. نرشّح سلة أو شوبيفاي أو ووردبريس عندما تناسب احتياجك، ونبني بكود مخصص عندما تحتاج ما لا توفره هذه المنصات."}},{"q":{"en":"How long does a typical project take?","ar":"كم يستغرق المشروع عادةً؟"},"a":{"en":"A store or marketing site takes 4–8 weeks; platforms, ERP and CRM systems usually 3–6 months, delivered in weekly increments.","ar":"المتجر أو الموقع التعريفي من 4 إلى 8 أسابيع، والمنصات وأنظمة ERP وCRM عادةً من 3 إلى 6 أشهر، مع تسليمات أسبوعية."}},{"q":{"en":"Who owns the code?","ar":"لمن تعود ملكية الكود؟"},"a":{"en":"You do. Source code, accounts and documentation are handed over at launch.","ar":"لك بالكامل. نسلّمك الكود والحسابات والتوثيق عند الإطلاق."}}]'::jsonb, 'Development team', 'فريق البرمجة', 'Engineers who own the stack end to end — architecture, code, QA and DevOps.', 'مهندسون يتولّون المشروع من البنية حتى الإطلاق — كود واختبار وتشغيل.', '[{"en":"Web & mobile apps","ar":"تطبيقات ويب وجوال"},{"en":"Platforms & dashboards","ar":"منصات ولوحات تحكم"},{"en":"Integrations & APIs","ar":"تكاملات وواجهات API"},{"en":"AI agents & automations","ar":"وكلاء ذكاء اصطناعي وأتمتة"}]'::jsonb, 'code-xml', 1, true),
  ('branding', 'Branding', 'الهوية التجارية', 'Identities built on a system.', 'هويات مبنية على نظام واضح.', 'Strategy, naming and visual identity designed as a system — so your brand stays sharp on every screen, shelf and campaign.', 'استراتيجية وتسمية وهوية بصرية مصممة كنظام متكامل، لتبقى علامتك واضحة وقوية على كل شاشة وكل حملة.', '[{"en":"Brand strategy","ar":"استراتيجية العلامة"},{"en":"Logo & visual identity","ar":"الشعار والهوية البصرية"},{"en":"Brand guidelines","ar":"دليل استخدام الهوية"},{"en":"Packaging & print","ar":"التغليف والمطبوعات"},{"en":"UI design systems","ar":"أنظمة تصميم الواجهات"}]'::jsonb, 'construction', '[{"q":{"en":"What does a full brand identity include?","ar":"ماذا تشمل الهوية التجارية الكاملة؟"},"a":{"en":"Strategy, logo system, colour and type, imagery direction, key applications and a guidelines document your team can use.","ar":"الاستراتيجية ونظام الشعار والألوان والخطوط وأسلوب الصور وأهم التطبيقات، مع دليل استخدام يعتمد عليه فريقك."}},{"q":{"en":"Do you design bilingual identities?","ar":"هل تصممون هويات ثنائية اللغة؟"},"a":{"en":"Yes — Arabic and English are designed together from day one so both feel native, not translated.","ar":"نعم، نصمم العربية والإنجليزية معًا من اليوم الأول حتى تبدو كل لغة أصلية لا مترجمة."}},{"q":{"en":"Can you refresh an existing brand?","ar":"هل يمكن تطوير هوية موجودة بدل تغييرها؟"},"a":{"en":"Often that''s the smarter move. We audit what works, keep the equity and modernise the rest.","ar":"غالبًا يكون هذا الخيار الأذكى. نراجع ما ينجح ونحافظ على قيمته ونحدّث الباقي."}}]'::jsonb, 'Brand team', 'فريق الهوية', 'Strategists and designers who turn what you stand for into a system people remember.', 'استراتيجيون ومصممون يحوّلون ما تمثّله علامتك إلى نظام بصري لا يُنسى.', '[{"en":"Brand strategy & naming","ar":"الاستراتيجية والتسمية"},{"en":"Logo & identity systems","ar":"الشعار وأنظمة الهوية"},{"en":"Guidelines & toolkits","ar":"الأدلة وأدوات العلامة"},{"en":"Product & UI design","ar":"تصميم المنتجات والواجهات"}]'::jsonb, 'pen-tool', 2, true),
  ('marketing', 'Marketing', 'التسويق الرقمي', 'Growth you can measure.', 'نمو تقيسه بالأرقام.', 'Performance campaigns, content and social built around data — every dirham, riyal and pound tracked back to revenue.', 'حملات أداء ومحتوى وإدارة منصات اجتماعية مبنية على البيانات، مع تتبّع كل ميزانية حتى تتحول إلى مبيعات.', '[{"en":"Performance ads","ar":"إعلانات الأداء"},{"en":"Social media management","ar":"إدارة منصات التواصل"},{"en":"Content & campaigns","ar":"المحتوى والحملات"},{"en":"SEO & analytics","ar":"تحسين محركات البحث والتحليلات"},{"en":"Marketing automation","ar":"أتمتة التسويق"}]'::jsonb, 'chart', '[{"q":{"en":"Which platforms do you advertise on?","ar":"على أي منصات تُطلقون الإعلانات؟"},"a":{"en":"Meta, Google, TikTok and Snapchat, chosen by where your customers actually are in each market.","ar":"ميتا وجوجل وتيك توك وسناب شات، ونختار حسب أماكن وجود عملائك فعلًا في كل سوق."}},{"q":{"en":"How do you report results?","ar":"كيف تقدّمون تقارير النتائج؟"},"a":{"en":"A live dashboard plus a monthly review focused on revenue, cost per acquisition and return on ad spend.","ar":"لوحة متابعة مباشرة ومراجعة شهرية تركّز على المبيعات وتكلفة العميل والعائد على الإنفاق الإعلاني."}},{"q":{"en":"Is there a minimum budget?","ar":"هل هناك حد أدنى للميزانية؟"},"a":{"en":"We''ll tell you honestly what budget your goals need during the first call — no long-term lock-in.","ar":"نخبرك بصراحة في أول مكالمة بالميزانية التي تحتاجها أهدافك، ودون التزام طويل."}}]'::jsonb, 'Marketing team', 'فريق التسويق', 'Media buyers, creators and analysts focused on one number: profitable growth.', 'مشترو إعلانات وصنّاع محتوى ومحللون يركّزون على رقم واحد: نمو مربح.', '[{"en":"Paid media on Meta, Google & TikTok","ar":"إعلانات ميتا وجوجل وتيك توك"},{"en":"Content & social calendars","ar":"خطط المحتوى والمنصات"},{"en":"SEO & landing pages","ar":"تحسين البحث وصفحات الهبوط"},{"en":"Reporting & attribution","ar":"التقارير وقياس الأثر"}]'::jsonb, 'trending-up', 3, true);
insert into public.solutions (slug, features, kind, title_en, title_ar, description_en, description_ar, icon, sort_order, published) values
  ('e-commerce', '[{"en":"Custom or platform-based stores","ar":"متاجر مخصصة أو على المنصات"},{"en":"Payment gateways: Mada, Apple Pay, Tabby, Tamara","ar":"بوابات الدفع: مدى وApple Pay وتابي وتمارا"},{"en":"Shipping & stock integrations","ar":"تكامل الشحن والمخزون"},{"en":"Conversion-focused UX","ar":"تجربة شراء ترفع المبيعات"}]'::jsonb, 'solution', 'E-commerce', 'التجارة الإلكترونية', 'Stores that convert — custom or on Salla and Shopify, wired to payments, shipping and stock.', 'متاجر تحقق مبيعات — مخصصة أو على سلة وشوبيفاي، مربوطة بالدفع والشحن والمخزون.', 'shopping-bag', 1, true),
  ('e-learning', '[{"en":"Video courses & live classes","ar":"دورات مسجّلة وحصص مباشرة"},{"en":"Quizzes, certificates & progress tracking","ar":"اختبارات وشهادات وتتبع التقدّم"},{"en":"Subscriptions & bundles","ar":"اشتراكات وباقات"},{"en":"Arabic-first student experience","ar":"تجربة عربية أولًا للمتعلم"}]'::jsonb, 'solution', 'E-learning', 'منصات التعليم الإلكتروني', 'Course platforms with video, quizzes, certificates and subscriptions your students enjoy using.', 'منصات دورات بالفيديو والاختبارات والشهادات والاشتراكات، بتجربة يستمتع بها المتعلمون.', 'graduation-cap', 2, true),
  ('erp', '[{"en":"Inventory & warehouses","ar":"المخزون والمستودعات"},{"en":"Purchasing & finance","ar":"المشتريات والمالية"},{"en":"HR & payroll","ar":"الموارد البشرية والرواتب"},{"en":"Role-based dashboards","ar":"لوحات تحكم حسب الصلاحيات"}]'::jsonb, 'solution', 'ERP', 'أنظمة ERP', 'Inventory, finance, HR and operations in one system shaped around how your company actually works.', 'المخزون والمالية والموارد البشرية والعمليات في نظام واحد مصمم حول طريقة عمل شركتك.', 'boxes', 3, true),
  ('crm', '[{"en":"Visual sales pipeline","ar":"مسار مبيعات مرئي"},{"en":"WhatsApp & email in one inbox","ar":"واتساب والبريد في صندوق واحد"},{"en":"Lead scoring with AI","ar":"تقييم العملاء بالذكاء الاصطناعي"},{"en":"Automated follow-ups","ar":"متابعات تلقائية"}]'::jsonb, 'solution', 'CRM', 'أنظمة CRM', 'Pipelines, follow-ups and WhatsApp in one place, so no lead slips through the cracks.', 'مسارات البيع والمتابعات وواتساب في مكان واحد، حتى لا يضيع أي عميل محتمل.', 'contact', 4, true),
  ('salla', '[{"en":"Custom Salla themes","ar":"قوالب سلة مخصصة"},{"en":"Salla apps & integrations","ar":"تطبيقات وتكاملات سلة"},{"en":"Migration to Salla","ar":"النقل إلى سلة"},{"en":"Speed & SEO optimisation","ar":"تحسين السرعة ومحركات البحث"}]'::jsonb, 'platform', 'Salla', 'سلة', 'Themes, apps and integrations for Salla stores across Saudi Arabia and the Gulf.', 'قوالب وتطبيقات وتكاملات لمتاجر سلة في السعودية والخليج.', 'si:siSalla', 5, true),
  ('shopify', '[{"en":"Custom themes & sections","ar":"قوالب وأقسام مخصصة"},{"en":"Checkout extensions","ar":"إضافات صفحة الدفع"},{"en":"Headless storefronts","ar":"واجهات Headless"},{"en":"Multi-currency for the Gulf","ar":"تعدد العملات لأسواق الخليج"}]'::jsonb, 'platform', 'Shopify', 'شوبيفاي', 'Custom themes, checkout extensions and headless storefronts built to scale.', 'قوالب مخصصة وإضافات للدفع وواجهات Headless قابلة للتوسع.', 'si:siShopify', 6, true),
  ('wordpress', '[{"en":"Fast custom WordPress themes","ar":"قوالب ووردبريس مخصصة وسريعة"},{"en":"WooCommerce stores","ar":"متاجر ووكومرس"},{"en":"Security & maintenance","ar":"الحماية والصيانة"},{"en":"Easy editing for your team","ar":"تعديل سهل لفريقك"}]'::jsonb, 'platform', 'WordPress', 'ووردبريس', 'Fast, secure WordPress and WooCommerce sites your team can edit with confidence.', 'مواقع ووردبريس وووكومرس سريعة وآمنة، يسهل على فريقك تعديلها بثقة.', 'si:siWordpress', 7, true);
insert into public.project_categories (slug, name_en, name_ar, sort_order) values
  ('development', 'Development', 'برمجة', 1),
  ('branding', 'Branding', 'هوية', 2),
  ('marketing', 'Marketing', 'تسويق', 3),
  ('ai', 'AI', 'ذكاء اصطناعي', 4);
insert into public.projects (cover_image, live_url, status, slug, challenge_en, challenge_ar, approach_en, approach_ar, results, services, title_en, title_ar, summary_en, summary_ar, category, tags, client_name, year, cover_style, featured, sort_order, content_en, content_ar) values
  (null, null, 'published', 'nakhla-salla-store', 'Nakhla''s old store was slow on mobile, gifting was buried in notes, and most orders arrived by WhatsApp instead of checkout.', 'كان متجر نخلة القديم بطيئًا على الجوال، وخيار الإهداء مخفيًا في الملاحظات، ومعظم الطلبات تصل عبر واتساب بدل صفحة الدفع.', 'We designed a custom Salla theme around gifting: a guided gift builder, delivery-slot picker and one-page checkout with Mada, Apple Pay and Tabby.', 'صممنا قالب سلة مخصصًا يتمحور حول الإهداء: أداة لتجهيز الهدية خطوة بخطوة، واختيار موعد التوصيل، ودفع من صفحة واحدة عبر مدى وApple Pay وتابي.', '[{"value":"+64%","label":{"en":"conversion rate","ar":"معدل التحويل"}},{"value":"2.1s","label":{"en":"mobile load time","ar":"زمن التحميل على الجوال"}},{"value":"-40%","label":{"en":"WhatsApp order requests","ar":"طلبات الشراء عبر واتساب"}}]'::jsonb, array['development', 'branding']::text[], 'Nakhla — Salla store rebuild', 'نخلة — إعادة بناء متجر سلة', 'A premium dates brand moved to a custom Salla theme with gifting flows and same-day delivery slots.', 'علامة تمور فاخرة انتقلت إلى قالب سلة مخصص مع تجربة إهداء ومواعيد توصيل في نفس اليوم.', 'development', array['Salla', 'E-commerce', 'UX']::text[], 'Nakhla', 2025, 'blocks', true, 1, null, null),
  (null, null, 'published', 'skyline-lead-agent', 'Skyline received hundreds of property enquiries a week on WhatsApp; agents spent hours answering the same questions and missed hot leads.', 'كانت سكايلاين تستقبل مئات الاستفسارات العقارية أسبوعيًا على واتساب، ويقضي الوكلاء ساعات في الرد على الأسئلة نفسها فتضيع الفرص الجادة.', 'We built an n8n workflow with an LLM agent that answers in Arabic and English, asks budget and area, scores the lead and books viewings straight into the CRM.', 'بنينا مسار عمل على n8n مع وكيل ذكي يرد بالعربية والإنجليزية، ويسأل عن الميزانية والمنطقة، ويقيّم العميل، ويحجز المعاينة مباشرة في نظام CRM.', '[{"value":"< 30s","label":{"en":"first response time","ar":"زمن أول رد"}},{"value":"3×","label":{"en":"qualified viewings","ar":"معاينات مؤهلة"}},{"value":"24/7","label":{"en":"coverage","ar":"تغطية على مدار الساعة"}}]'::jsonb, array['development']::text[], 'Skyline — WhatsApp lead agent', 'سكايلاين — وكيل واتساب للعملاء', 'An n8n + LLM agent that qualifies property leads on WhatsApp and books viewings into the CRM.', 'وكيل مبني على n8n ونموذج لغوي يؤهل عملاء العقارات على واتساب ويحجز المعاينات في نظام CRM.', 'ai', array['n8n', 'AI Agent', 'WhatsApp', 'CRM']::text[], 'Skyline Realty', 2025, 'flow', true, 2, null, null),
  (null, null, 'published', 'fitbox-rebrand', 'Fitbox had grown to nine branches with nine slightly different logos and no system to hold the brand together.', 'توسعت فيت بوكس إلى تسعة فروع بتسعة أشكال مختلفة للشعار، دون نظام يجمع الهوية.', 'A bold block-based identity, a signage and wayfinding system, and a launch campaign that turned the rebrand into a reason to visit.', 'هوية جريئة مبنية على المكعبات، ونظام لافتات وإرشاد داخلي، وحملة إطلاق جعلت الهوية الجديدة سببًا لزيارة النادي.', '[{"value":"9","label":{"en":"branches rolled out","ar":"فروع طُبّقت فيها الهوية"}},{"value":"+38%","label":{"en":"new memberships in launch month","ar":"اشتراكات جديدة في شهر الإطلاق"}},{"value":"1","label":{"en":"system for every touchpoint","ar":"نظام واحد لكل نقاط التواصل"}}]'::jsonb, array['branding', 'marketing']::text[], 'Fitbox — rebrand & launch', 'فيت بوكس — هوية جديدة وإطلاق', 'A gym chain''s new identity, signage system and launch campaign across three cities.', 'هوية جديدة لسلسلة نوادٍ رياضية، مع نظام لافتات وحملة إطلاق في ثلاث مدن.', 'branding', array['Identity', 'Guidelines', 'Campaign']::text[], 'Fitbox', 2024, 'brackets', true, 3, null, null),
  (null, null, 'published', 'gulf-supply-erp', 'Inventory lived in spreadsheets, purchasing in email, and finance closed the month by hand — a week of work every month.', 'كان المخزون في جداول، والمشتريات في البريد، والمالية تغلق الشهر يدويًا — أسبوع عمل كامل كل شهر.', 'A custom ERP with Arabic-first dashboards, approval flows and role-based access, integrated with their accounting system and barcode scanners.', 'نظام ERP مخصص بلوحات تحكم عربية أولًا، ومسارات موافقة، وصلاحيات حسب الدور، مع ربطه بنظام المحاسبة وقارئات الباركود.', '[{"value":"1 day","label":{"en":"month-end close","ar":"لإغلاق نهاية الشهر"}},{"value":"-27%","label":{"en":"stock-outs","ar":"نفاد المخزون"}},{"value":"120","label":{"en":"daily active users","ar":"مستخدم يومي"}}]'::jsonb, array['development']::text[], 'Gulf Supply — custom ERP', 'الخليج للتوريد — نظام ERP مخصص', 'Inventory, purchasing and finance in one system with Arabic-first dashboards and role-based access.', 'المخزون والمشتريات والمالية في نظام واحد، بلوحات تحكم عربية أولًا وصلاحيات حسب الدور.', 'development', array['ERP', 'Next.js', 'Dashboards']::text[], 'Gulf Supply Co.', 2024, 'grid', true, 4, null, null),
  (null, null, 'published', 'maharat-performance', 'Maharat needed to fill two intakes in a crowded market where cost per lead kept rising every season.', 'احتاجت مهارات لملء دفعتين في سوق مزدحم ترتفع فيه تكلفة العميل المحتمل كل موسم.', 'Full-funnel Meta and Google campaigns, fast bilingual landing pages and an automated WhatsApp follow-up that booked placement calls.', 'حملات متكاملة على ميتا وجوجل، وصفحات هبوط سريعة باللغتين، ومتابعة تلقائية على واتساب لحجز مكالمات تحديد المستوى.', '[{"value":"-46%","label":{"en":"cost per lead","ar":"تكلفة العميل المحتمل"}},{"value":"2","label":{"en":"intakes filled early","ar":"دفعات اكتملت مبكرًا"}},{"value":"5.4×","label":{"en":"return on ad spend","ar":"العائد على الإنفاق الإعلاني"}}]'::jsonb, array['marketing', 'development']::text[], 'Maharat — enrolment campaign', 'مهارات — حملة التسجيل', 'Full-funnel Meta and Google campaigns that filled two intakes ahead of schedule.', 'حملات متكاملة على ميتا وجوجل ملأت دفعتين من الطلاب قبل الموعد المحدد.', 'marketing', array['Meta Ads', 'Google Ads', 'Landing pages']::text[], 'Maharat Academy', 2025, 'chart', true, 5, null, null),
  (null, null, 'published', 'souq-ops-automation', 'Every Shopify order was copied by hand into the ERP, invoiced, then booked with a courier — slow and error-prone at peak season.', 'كان كل طلب على شوبيفاي يُنسخ يدويًا إلى نظام ERP ثم تُصدر فاتورته ويُحجز شحنه — عملية بطيئة وكثيرة الأخطاء في المواسم.', 'n8n workflows that sync orders, issue e-invoices, book couriers and send WhatsApp tracking updates automatically.', 'مسارات عمل على n8n تزامن الطلبات، وتُصدر الفواتير الإلكترونية، وتحجز الشحن، وترسل تحديثات التتبع على واتساب تلقائيًا.', '[{"value":"0","label":{"en":"manual order entries","ar":"إدخال يدوي للطلبات"}},{"value":"6 h","label":{"en":"saved every day","ar":"توفير يومي"}},{"value":"99.8%","label":{"en":"order accuracy","ar":"دقة الطلبات"}}]'::jsonb, array['development']::text[], 'Souq Box — order automation', 'سوق بوكس — أتمتة الطلبات', 'Orders, invoices and courier bookings synced automatically between Shopify, the ERP and WhatsApp.', 'مزامنة تلقائية للطلبات والفواتير وحجوزات الشحن بين شوبيفاي ونظام ERP وواتساب.', 'ai', array['n8n', 'Shopify', 'Automation']::text[], 'Souq Box', 2025, 'flow', true, 6, null, null);
insert into public.posts (slug, title_en, title_ar, excerpt_en, excerpt_ar, content_en, content_ar, cover_image, cover_style, author_name, tags, reading_minutes, status, published_at) values
  ('whatsapp-ai-agent-n8n', 'How a WhatsApp AI agent built on n8n qualifies leads while you sleep', 'كيف يؤهل وكيل ذكاء اصطناعي على واتساب ومبني بـ n8n عملاءك وأنت نائم', 'Most Gulf and Egyptian customers start on WhatsApp. Here''s the workflow we use to answer instantly, ask the right questions and hand sales a qualified lead.', 'معظم العملاء في الخليج ومصر يبدؤون من واتساب. هذا هو مسار العمل الذي نستخدمه للرد فورًا وطرح الأسئلة الصحيحة وتسليم فريق المبيعات عميلًا جاهزًا.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"WhatsApp is where buying conversations start in our markets. The problem is speed: a lead that waits an hour is often a lead lost to a competitor who replied in five minutes."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"The workflow"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"A WhatsApp message triggers the n8n workflow."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"An AI agent detects the language and intent."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"It asks two or three qualifying questions — budget, timeline, location."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The lead is scored and created in the CRM."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Hot leads are routed to a human with the full conversation."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Why n8n"}]},{"type":"paragraph","content":[{"type":"text","text":"n8n gives us visual workflows, self-hosting for data-sensitive clients and hundreds of integrations — so the agent can check stock, prices or bookings in your real systems instead of guessing."}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"type":"text","text":"The best automation doesn''t replace your team. It makes sure they only spend time on conversations that matter."}]}]},{"type":"paragraph","content":[{"type":"text","text":"If your team answers the same ten questions every day, that''s the first workflow worth automating."}]}]}'::jsonb, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"واتساب هو المكان الذي تبدأ منه محادثات الشراء في أسواقنا. المشكلة في السرعة: العميل الذي ينتظر ساعة غالبًا يذهب لمنافس ردّ عليه خلال خمس دقائق."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"مسار العمل"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"رسالة واتساب تُطلق مسار العمل على n8n."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"وكيل ذكي يحدد اللغة والمقصود من الرسالة."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"يطرح سؤالين أو ثلاثة للتأهيل: الميزانية والتوقيت والموقع."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"يُقيَّم العميل ويُسجَّل في نظام CRM."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"العملاء الجاهزون يُحوَّلون لموظف مع المحادثة كاملة."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"لماذا n8n"}]},{"type":"paragraph","content":[{"type":"text","text":"يمنحنا n8n مسارات عمل مرئية، وإمكانية التشغيل على خوادم العميل للبيانات الحساسة، ومئات التكاملات — فيستطيع الوكيل التحقق من المخزون أو الأسعار أو الحجوزات في أنظمتك الحقيقية بدل التخمين."}]},{"type":"blockquote","content":[{"type":"paragraph","content":[{"type":"text","text":"أفضل أتمتة لا تستبدل فريقك، بل تضمن أن وقته يذهب فقط للمحادثات المهمة."}]}]},{"type":"paragraph","content":[{"type":"text","text":"إذا كان فريقك يجيب على الأسئلة العشرة نفسها كل يوم، فهذا أول مسار يستحق الأتمتة."}]}]}'::jsonb, null, 'flow', 'CODEX Team', array['AI', 'n8n', 'WhatsApp']::text[], 4, 'published', '2026-09-18T09:00:00Z'),
  ('salla-vs-shopify-2026', 'Salla or Shopify? Choosing the right platform for a Gulf store', 'سلة أم شوبيفاي؟ كيف تختار المنصة المناسبة لمتجرك في الخليج', 'Both are excellent — for different businesses. A practical comparison on payments, shipping, apps and growth.', 'كلتاهما ممتازة — لكن لأنشطة مختلفة. مقارنة عملية في الدفع والشحن والتطبيقات والنمو.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"We build on both every month, so we get this question a lot. The honest answer: it depends on where you sell and how fast you plan to grow."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Choose Salla when"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Saudi Arabia is your main market."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"You want local payments and shipping working out of the box."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Your team prefers an Arabic-first dashboard."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Choose Shopify when"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"You sell across several countries and currencies."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"You need advanced apps or a headless storefront."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"You plan to scale catalogue and traffic quickly."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Either way, the theme, speed and checkout experience decide most of your conversion rate — that''s where custom work pays off."}]}]}'::jsonb, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"نبني على المنصتين كل شهر، لذلك يتكرر علينا هذا السؤال كثيرًا. الإجابة الصادقة: يعتمد الأمر على أين تبيع وبأي سرعة تخطط للنمو."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"اختر سلة عندما"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"تكون السعودية سوقك الأساسي."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"تريد الدفع والشحن المحليين جاهزين من البداية."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"يفضّل فريقك لوحة تحكم عربية أولًا."}]}]}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"اختر شوبيفاي عندما"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"تبيع في عدة دول وبعملات مختلفة."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"تحتاج تطبيقات متقدمة أو واجهة Headless."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"تخطط لتوسيع المنتجات والزيارات بسرعة."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"في الحالتين، القالب والسرعة وتجربة الدفع تحدد معظم نسبة التحويل — وهنا يظهر أثر العمل المخصص."}]}]}'::jsonb, null, 'blocks', 'CODEX Team', array['E-commerce', 'Salla', 'Shopify']::text[], 5, 'published', '2026-08-27T09:00:00Z'),
  ('bilingual-brand-identity', 'Designing a brand that feels native in Arabic and English', 'كيف تصمم هوية تبدو أصلية بالعربية والإنجليزية معًا', 'Translation is not localisation. Five rules we follow so both languages carry the same personality.', 'الترجمة ليست توطينًا. خمس قواعد نتبعها لتحمل اللغتان الشخصية نفسها.', '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Too many regional brands design in English first and ''add Arabic'' at the end. The result always shows: cramped type, broken rhythm and a voice that sounds translated."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"Five rules"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Pick both typefaces together and test them side by side."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Give Arabic more line-height — it needs room to breathe."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Write copy natively in each language; never translate taglines."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Mirror layouts properly in RTL, but never mirror the logo."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Check every motion and icon for direction."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Done right, customers in Riyadh, Dubai and Cairo feel the brand was made for them — because it was."}]}]}'::jsonb, '{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"كثير من العلامات في المنطقة تُصمَّم بالإنجليزية أولًا ثم ''تُضاف'' العربية في النهاية. والنتيجة تظهر دائمًا: خطوط مزدحمة وإيقاع مكسور ونبرة تبدو مترجمة."}]},{"type":"heading","attrs":{"level":2},"content":[{"type":"text","text":"خمس قواعد"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"اختر الخطين معًا واختبرهما جنبًا إلى جنب."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"امنح العربية تباعدًا أكبر بين الأسطر — فهي تحتاج مساحة."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"اكتب النصوص بكل لغة مباشرة، ولا تترجم الشعارات."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"اعكس التصميم بشكل صحيح من اليمين لليسار، لكن لا تعكس الشعار أبدًا."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"راجع اتجاه كل حركة وكل أيقونة."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"عندما يُنفَّذ ذلك جيدًا، يشعر العملاء في الرياض ودبي والقاهرة أن العلامة صُممت لهم — لأنها كذلك فعلًا."}]}]}'::jsonb, null, 'brackets', 'CODEX Team', array['Branding', 'RTL', 'Arabic']::text[], 3, 'published', '2026-08-05T09:00:00Z');
insert into public.testimonials (quote_en, quote_ar, author_name, author_role_en, author_role_ar, company, country, avatar_url, sort_order, published) values
  ('CODEX rebuilt our Salla store and the checkout flow in six weeks. Conversion went up and support tickets went down.', 'أعاد فريق CODEX بناء متجرنا على سلة وتجربة الدفع خلال ستة أسابيع. ارتفعت المبيعات وانخفضت طلبات الدعم.', 'Faisal Al-Harbi', 'Founder', 'المؤسس', 'Nakhla Dates (placeholder)', 'SA', null, 1, true),
  ('Their n8n agent now qualifies our leads on WhatsApp before a human ever sees them. Our sales team finally talks to the right people.', 'وكيل n8n الذي بنوه يؤهل العملاء المحتملين على واتساب قبل أن يصلوا لفريقنا. أصبح فريق المبيعات يتحدث مع العملاء المناسبين فقط.', 'Mariam Adel', 'Head of Sales', 'مديرة المبيعات', 'Skyline Realty (placeholder)', 'AE', null, 2, true),
  ('One team for brand, site and ads meant no finger-pointing. The rebrand launched on time and the campaign paid for itself in a month.', 'وجود فريق واحد للهوية والموقع والإعلانات أنهى تبادل اللوم. أُطلقت الهوية الجديدة في موعدها وغطّت الحملة تكلفتها خلال شهر.', 'Omar Khaled', 'CEO', 'الرئيس التنفيذي', 'Fitbox (placeholder)', 'EG', null, 3, true),
  ('The ERP they built fits how we actually work. Month-end closing went from a week to a single day.', 'نظام ERP الذي بنوه يناسب طريقة عملنا فعلًا. إغلاق نهاية الشهر أصبح يومًا واحدًا بدل أسبوع.', 'Hamad Al-Sabah', 'Operations Director', 'مدير العمليات', 'Gulf Supply Co. (placeholder)', 'KW', null, 4, true),
  ('Our e-learning platform handles thousands of students without breaking a sweat — and it looks like us.', 'منصتنا التعليمية تخدم آلاف الطلاب بسلاسة تامة — وتعكس هويتنا بوضوح.', 'Salma Al-Busaidi', 'Academic Director', 'المديرة الأكاديمية', 'Maharat Academy (placeholder)', 'OM', null, 5, true);
